"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "Telefondaki tüm oyunlar tek yerde, rekorların ve oynadığın son oyunla birlikte. Telefondaki tüm oyunlar tek yerde, rekorların ve oynadığın son oyunla birlikte.",
